def extract_start_year(year_str):
    if not isinstance(year_str, str):
        try:
            return int(year_str)
        except:
            return -9999
    parts = year_str.split(' - ')
    start_part = parts[0]
    try:
        return int(start_part)
    except ValueError:
        return -9999

